import React, { useState } from 'react';
import StockSearch from './components/StockSearch';
import StockTable from './components/StockTable';
import { Stock } from './types/Stock';

const App: React.FC = () => {
    const [stocks, setStocks] = useState<Stock[]>([]);

    const handleStockFound = (stock: Stock) => {
        setStocks(prevStocks => {
            const exists = prevStocks.some(s => s.symbol === stock.symbol);
            if (exists) {
                return prevStocks.map(s => s.symbol === stock.symbol ? stock : s);
            }
            return [...prevStocks, stock];
        });
    };

    return (
        <div className="App">
            <h1>BörsVy</h1>
            <StockSearch onStockFound={handleStockFound} />
            <StockTable stocks={stocks} />
        </div>
    );
};

export default App;
